// === Tab: mySketch ===
// let Risou
// https://risoume.github.io/

let colors = ["#D1313D", "#E5625C", "#F9BF76", "#8EB2C5", "#615375"];
let colorNode = ["#9DC9AC", "#FFFEC7", "#F56218", "#FF9D2E", "#919167"];

let n;
let numTriangles = 5;
let r = 5;
let s;
let mult = 0.8;
let x1, y1, x2, y2, x3, y3;

function setup() {
  createCanvas(600, 600);
  rectMode(RADIUS);
  noLoop();
  init();
}

function init() {
  n = int(random(4, 8));
  s = width/(n+1);
}

function draw() {
  background("#fffbe6");
  for (i = 0; i < n; i++) {
    for (j = 0; j < n; j++) {
      triangles((i+1)*s, (j+1)*s, s*mult/2);
    }
  }
}

function triangles(x, y, s) {
  pushMatrix();
  translate(-s, -s);
  for (i = 0; i < numTriangles; i++) {
    x1 = int(random(x, x+2*s));
    y1 = int(random(y, y+2*s));
    x2 = int(random(x, x+2*s));
    y2 = int(random(y, y+2*s));
    x3 = int(random(x, x+2*s));
    y3 = int(random(y, y+2*s));
    tri();
  }
  popMatrix();
}

function tri() {
  stroke(colors[int(random(colors.length))]);
  noFill();
  triangle(x1, y1, x2, y2, x3, y3);
  noStroke();
  fill(colorNode[int(random(colorNode.length))]);
  ellipse(x1, y1, r, r);
  rect(x2, y2, r/2, r/2);
  ellipse(x3, y3, r, r);
}

function mouseReleased() {
  init();
  redraw();
}

